package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen2Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> config;
    private AnnotationIntrospector ai;
    private JavaType baseType;
    private AnnotatedMember property;

    // Test hierarchy
    public static class Base {}
    public static class Sub1 extends Base {}
    public static class Sub2 extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        config = mock(MapperConfig.class);
        ai = mock(AnnotationIntrospector.class);
        baseType = mock(JavaType.class);
        property = mock(AnnotatedMember.class);

        when(config.getAnnotationIntrospector()).thenReturn(ai);
        when(baseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectWithOnlyBaseType() {
        // Scenario: No property annotations, no registered subtypes. 
        // Should return at least the base type itself.

        when(ai.findSubtypes(property)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }

    @Test
    public void testCollectWithPropertyAnnotations() {
        // Scenario: Property has subtypes defined via AnnotationIntrospector
        NamedType namedSub1 = new NamedType(Sub1.class, "sub1");
        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(namedSub1));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
    }

    @Test
    public void testCollectWithRegisteredSubtypes() {
        // Scenario: Subtypes registered via registerSubtypes method
        resolver.registerSubtypes(Sub1.class, Sub2.class);

        // Ensure they are subtypes of Base
        when(ai.findSubtypes(property)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub2.class)));
    }

    @Test
    public void testCollectWithRegisteredNonSubtypes() {
        // Scenario: Registered subtypes that are NOT assignable from base type.
        // They should be ignored by the if (rawBase.isAssignableFrom(subtype.getType())) check.
        resolver.registerSubtypes(Unrelated.class);

        when(ai.findSubtypes(property)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        // Should contain Base, but NOT Unrelated
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
        assertFalse(result.stream().anyMatch(nt -> nt.getType().equals(Unrelated.class)));
    }

    @Test
    public void testFullPrecedenceStack() {
        // Scenario: 
        // 1. Hierarchy (Base)
        // 2. Property (Sub1)
        // 3. Registered (Sub2)
        // All should be collected.

        resolver.registerSubtypes(Sub2.class);
        NamedType propertyType = new NamedType(Sub1.class, "propSub");
        when(ai.findSubtypes(property)).thenReturn(Collections.singletonList(propertyType));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);

        assertNotNull(result);
        List<Class<?>> types = result.stream().map(NamedType::getType).toList();
        assertTrue(types.contains(Base.class));
        assertTrue(types.contains(Sub1.class));
        assertTrue(types.contains(Sub2.class));
    }

    @Test
    public void testPropertyIsNull() {
        // Scenario: property is null, should not crash and skip the findSubtypes block
        when(ai.findSubtypes(any())).thenReturn(Collections.singletonList(new NamedType(Sub1.class, "sub")));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, null, baseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
        // Sub1 should not be there because property was null
        assertFalse(result.stream().anyMatch(nt -> nt.getType().equals(Sub1.class)));
    }

    @Test
    public void testRegisteredSubtypesIsNull() {
        // Scenario: _registeredSubtypes is null (though constructor usually initializes it)
        // Since we can't easily null out a private field without reflection, 
        // we rely on the fact that if we haven't called registerSubtypes, 
        // it behaves as the "null" or empty case.

        when(ai.findSubtypes(property)).thenReturn(null);
        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(config, property, baseType);
        assertNotNull(result);
    }
}
